import { Schema } from 'effect'

export const AccountAnnualRevenueSchema = Schema.Struct({
  amount: Schema.optionalKey(
    Schema.NullOr(Schema.Number.check(Schema.isInt())).annotate({
      description:
        'A non-negative integer representing the amount in the [smallest currency unit](/currencies#zero-decimal).',
    }),
  ),
  currency: Schema.optionalKey(
    Schema.NullOr(Schema.String).annotate({
      description:
        'Three-letter [ISO currency code](https://www.iso.org/iso-4217-currency-codes.html), in lowercase. Must be a [supported currency](https://stripe.com/docs/currencies).',
    }),
  ),
  fiscal_year_end: Schema.optionalKey(
    Schema.NullOr(
      Schema.String.check(
        Schema.makeFilter((input) => [...input].length <= 5000, {
          expected: 'a string of at most 5000 characters',
        }),
      ),
    ).annotate({
      description:
        'The close-out date of the preceding fiscal year in ISO 8601 format. E.g. 2023-12-31 for the 31st of December, 2023.',
    }),
  ),
}).annotate({ description: '' })

export type AccountAnnualRevenueSchema = Schema.Schema.Type<typeof AccountAnnualRevenueSchema>

export const AccountMonthlyEstimatedRevenueSchema = Schema.Struct({
  amount: Schema.Number.check(Schema.isInt()).annotate({
    description:
      'A non-negative integer representing how much to charge in the [smallest currency unit](/currencies#zero-decimal).',
  }),
  currency: Schema.String.annotate({
    description:
      'Three-letter [ISO currency code](https://www.iso.org/iso-4217-currency-codes.html), in lowercase. Must be a [supported currency](https://stripe.com/docs/currencies).',
  }),
}).annotate({ description: '' })

export type AccountMonthlyEstimatedRevenueSchema = Schema.Schema.Type<
  typeof AccountMonthlyEstimatedRevenueSchema
>

export const AddressSchema = Schema.Struct({
  city: Schema.optionalKey(
    Schema.NullOr(
      Schema.String.check(
        Schema.makeFilter((input) => [...input].length <= 5000, {
          expected: 'a string of at most 5000 characters',
        }),
      ),
    ).annotate({ description: 'City, district, suburb, town, or village.' }),
  ),
  country: Schema.optionalKey(
    Schema.NullOr(
      Schema.String.check(
        Schema.makeFilter((input) => [...input].length <= 5000, {
          expected: 'a string of at most 5000 characters',
        }),
      ),
    ).annotate({
      description:
        'Two-letter country code ([ISO 3166-1 alpha-2](https://en.wikipedia.org/wiki/ISO_3166-1_alpha-2)).',
    }),
  ),
  line1: Schema.optionalKey(
    Schema.NullOr(
      Schema.String.check(
        Schema.makeFilter((input) => [...input].length <= 5000, {
          expected: 'a string of at most 5000 characters',
        }),
      ),
    ).annotate({ description: 'Address line 1, such as the street, PO Box, or company name.' }),
  ),
  line2: Schema.optionalKey(
    Schema.NullOr(
      Schema.String.check(
        Schema.makeFilter((input) => [...input].length <= 5000, {
          expected: 'a string of at most 5000 characters',
        }),
      ),
    ).annotate({ description: 'Address line 2, such as the apartment, suite, unit, or building.' }),
  ),
  postal_code: Schema.optionalKey(
    Schema.NullOr(
      Schema.String.check(
        Schema.makeFilter((input) => [...input].length <= 5000, {
          expected: 'a string of at most 5000 characters',
        }),
      ),
    ).annotate({ description: 'ZIP or postal code.' }),
  ),
  state: Schema.optionalKey(
    Schema.NullOr(
      Schema.String.check(
        Schema.makeFilter((input) => [...input].length <= 5000, {
          expected: 'a string of at most 5000 characters',
        }),
      ),
    ).annotate({
      description:
        'State, county, province, or region ([ISO 3166-2](https://en.wikipedia.org/wiki/ISO_3166-2)).',
    }),
  ),
}).annotate({ description: '' })

export type AddressSchema = Schema.Schema.Type<typeof AddressSchema>

export const AccountBusinessProfileSchema = Schema.Struct({
  annual_revenue: Schema.optionalKey(
    Schema.NullOr(Schema.Union([AccountAnnualRevenueSchema])).annotate({
      description: "The applicant's gross annual revenue for its preceding fiscal year.",
    }),
  ),
  estimated_worker_count: Schema.optionalKey(
    Schema.NullOr(Schema.Number.check(Schema.isInt())).annotate({
      description:
        'An estimated upper bound of employees, contractors, vendors, etc. currently working for the business.',
    }),
  ),
  mcc: Schema.optionalKey(
    Schema.NullOr(
      Schema.String.check(
        Schema.makeFilter((input) => [...input].length <= 5000, {
          expected: 'a string of at most 5000 characters',
        }),
      ),
    ).annotate({
      description:
        '[The merchant category code for the account](/connect/setting-mcc). MCCs are used to classify businesses based on the goods or services they provide.',
    }),
  ),
  minority_owned_business_designation: Schema.optionalKey(
    Schema.NullOr(
      Schema.Array(
        Schema.Literals([
          'lgbtqi_owned_business',
          'minority_owned_business',
          'none_of_these_apply',
          'prefer_not_to_answer',
          'women_owned_business',
        ]),
      ),
    ).annotate({
      description:
        'Whether the business is a minority-owned, women-owned, and/or LGBTQI+ -owned business.',
    }),
  ),
  monthly_estimated_revenue: Schema.optionalKey(AccountMonthlyEstimatedRevenueSchema),
  name: Schema.optionalKey(
    Schema.NullOr(
      Schema.String.check(
        Schema.makeFilter((input) => [...input].length <= 5000, {
          expected: 'a string of at most 5000 characters',
        }),
      ),
    ).annotate({ description: 'The customer-facing business name.' }),
  ),
  product_description: Schema.optionalKey(
    Schema.NullOr(
      Schema.String.check(
        Schema.makeFilter((input) => [...input].length <= 40000, {
          expected: 'a string of at most 40000 characters',
        }),
      ),
    ).annotate({
      description:
        "Internal-only description of the product sold or service provided by the business. It's used by Stripe for risk and underwriting purposes.",
    }),
  ),
  specified_commercial_transactions_act_url: Schema.optionalKey(
    Schema.NullOr(
      Schema.String.check(
        Schema.makeFilter((input) => [...input].length <= 5000, {
          expected: 'a string of at most 5000 characters',
        }),
      ),
    ).annotate({
      description:
        "A link to the business's publicly available terms related to the Specified Commercial Transaction Act. Only used for accounts in Japan.",
    }),
  ),
  support_address: Schema.optionalKey(
    Schema.NullOr(Schema.Union([AddressSchema])).annotate({
      description: 'A publicly available mailing address for sending support issues to.',
    }),
  ),
  support_email: Schema.optionalKey(
    Schema.NullOr(
      Schema.String.check(
        Schema.makeFilter((input) => [...input].length <= 5000, {
          expected: 'a string of at most 5000 characters',
        }),
      ),
    ).annotate({
      description: 'A publicly available email address for sending support issues to.',
    }),
  ),
  support_phone: Schema.optionalKey(
    Schema.NullOr(
      Schema.String.check(
        Schema.makeFilter((input) => [...input].length <= 5000, {
          expected: 'a string of at most 5000 characters',
        }),
      ),
    ).annotate({ description: 'A publicly available phone number to call with support issues.' }),
  ),
  support_url: Schema.optionalKey(
    Schema.NullOr(
      Schema.String.check(
        Schema.makeFilter((input) => [...input].length <= 5000, {
          expected: 'a string of at most 5000 characters',
        }),
      ),
    ).annotate({ description: 'A publicly available website for handling support issues.' }),
  ),
  url: Schema.optionalKey(
    Schema.NullOr(
      Schema.String.check(
        Schema.makeFilter((input) => [...input].length <= 5000, {
          expected: 'a string of at most 5000 characters',
        }),
      ),
    ).annotate({ description: "The business's publicly available website." }),
  ),
}).annotate({ description: '' })

export type AccountBusinessProfileSchema = Schema.Schema.Type<typeof AccountBusinessProfileSchema>

