export const IssuingTokenSchema = Schema.Struct({
  card: Schema.Union([
    Schema.String.check(
      Schema.makeFilter((input) => [...input].length <= 5000, {
        expected: 'a string of at most 5000 characters',
      }),
    ),
    IssuingCardSchema,
  ]).annotate({ description: 'Card associated with this token.' }),
  created: Schema.Number.check(Schema.isInt()).annotate({
    description: 'Time at which the object was created. Measured in seconds since the Unix epoch.',
  }),
  device_fingerprint: Schema.optionalKey(
    Schema.NullOr(
      Schema.String.check(
        Schema.makeFilter((input) => [...input].length <= 5000, {
          expected: 'a string of at most 5000 characters',
        }),
      ),
    ).annotate({
      description:
        'The hashed ID derived from the device ID from the card network associated with the token.',
    }),
  ),
  id: Schema.String.check(
    Schema.makeFilter((input) => [...input].length <= 5000, {
      expected: 'a string of at most 5000 characters',
    }),
  ).annotate({ description: 'Unique identifier for the object.' }),
  last4: Schema.optionalKey(
    Schema.String.check(
      Schema.makeFilter((input) => [...input].length <= 5000, {
        expected: 'a string of at most 5000 characters',
      }),
    ).annotate({ description: 'The last four digits of the token.' }),
  ),
  livemode: Schema.Boolean.annotate({
    description:
      'If the object exists in live mode, the value is `true`. If the object exists in test mode, the value is `false`.',
  }),
  network: Schema.Literals(['mastercard', 'visa']).annotate({
    description: 'The token service provider / card network associated with the token.',
  }),
  network_data: Schema.optionalKey(IssuingNetworkTokenNetworkDataSchema),
  network_updated_at: Schema.Number.check(Schema.isInt()).annotate({
    description:
      'Time at which the token was last updated by the card network. Measured in seconds since the Unix epoch.',
  }),
  object: Schema.Literal('issuing.token').annotate({
    description:
      "String representing the object's type. Objects of the same type share the same value.",
  }),
  status: Schema.Literals(['active', 'deleted', 'requested', 'suspended']).annotate({
    description: 'The usage state of the token.',
  }),
  wallet_provider: Schema.optionalKey(
    Schema.Literals(['apple_pay', 'google_pay', 'samsung_pay']).annotate({
      description: 'The digital wallet for this token, if one was used.',
    }),
  ),
}).annotate({
  description:
    'An issuing token object is created when an issued card is added to a digital wallet. As a [card issuer](https://docs.stripe.com/issuing), you can [view and manage these tokens](https://docs.stripe.com/issuing/controls/token-management) through Stripe.',
})

