type PriceType = {
  active: boolean
  billing_scheme: 'per_unit' | 'tiered'
  created: number
  currency: string
  currency_options?: { [key: string]: Schema.Schema.Type<typeof CurrencyOptionSchema> }
  custom_unit_amount?: Schema.Schema.Type<typeof CustomUnitAmountSchema>
  id: string
  livemode: boolean
  lookup_key?: string | null
  metadata: { [key: string]: string }
  nickname?: string | null
  object: 'price'
  product:
    | string
    | Schema.Schema.Type<typeof ProductSchema>
    | Schema.Schema.Type<typeof DeletedProductSchema>
  recurring?: Schema.Schema.Type<typeof RecurringSchema>
  tax_behavior?: 'exclusive' | 'inclusive' | 'unspecified'
  tiers?: readonly Schema.Schema.Type<typeof PriceTierSchema>[]
  tiers_mode?: 'graduated' | 'volume'
  transform_quantity?: Schema.Schema.Type<typeof TransformQuantitySchema>
  type: 'one_time' | 'recurring'
  unit_amount?: number | null
  unit_amount_decimal?: string | null
}

export const PriceSchema: Schema.Codec<PriceType, unknown> = Schema.Struct({
  active: Schema.Boolean.annotate({
    description: 'Whether the price can be used for new purchases.',
  }),
  billing_scheme: Schema.Literals(['per_unit', 'tiered']).annotate({
    description:
      'Describes how to compute the price per period. Either `per_unit` or `tiered`. `per_unit` indicates that the fixed amount (specified in `unit_amount` or `unit_amount_decimal`) will be charged per unit in `quantity` (for prices with `usage_type=licensed`), or per unit of total usage (for prices with `usage_type=metered`). `tiered` indicates that the unit pricing will be computed using a tiering strategy as defined using the `tiers` and `tiers_mode` attributes.',
  }),
  created: Schema.Number.check(Schema.isInt()).annotate({
    description: 'Time at which the object was created. Measured in seconds since the Unix epoch.',
  }),
  currency: Schema.String.annotate({
    description:
      'Three-letter [ISO currency code](https://www.iso.org/iso-4217-currency-codes.html), in lowercase. Must be a [supported currency](https://stripe.com/docs/currencies).',
  }),
  currency_options: Schema.optionalKey(
    Schema.Record(Schema.String, CurrencyOptionSchema).annotate({
      description:
        'Prices defined in each available currency option. Each key must be a three-letter [ISO currency code](https://www.iso.org/iso-4217-currency-codes.html) and a [supported currency](https://stripe.com/docs/currencies).',
    }),
  ),
  custom_unit_amount: Schema.optionalKey(
    Schema.NullOr(Schema.Union([CustomUnitAmountSchema])).annotate({
      description:
        'When set, provides configuration for the amount to be adjusted by the customer during Checkout Sessions and Payment Links.',
    }),
  ),
  id: Schema.String.check(
    Schema.makeFilter((input) => [...input].length <= 5000, {
      expected: 'a string of at most 5000 characters',
    }),
  ).annotate({ description: 'Unique identifier for the object.' }),
  livemode: Schema.Boolean.annotate({
    description:
      'If the object exists in live mode, the value is `true`. If the object exists in test mode, the value is `false`.',
  }),
  lookup_key: Schema.optionalKey(
    Schema.NullOr(
      Schema.String.check(
        Schema.makeFilter((input) => [...input].length <= 5000, {
          expected: 'a string of at most 5000 characters',
        }),
      ),
    ).annotate({
      description:
        'A lookup key used to retrieve prices dynamically from a static string. This may be up to 200 characters.',
    }),
  ),
  metadata: Schema.Record(
    Schema.String,
    Schema.String.check(
      Schema.makeFilter((input) => [...input].length <= 500, {
        expected: 'a string of at most 500 characters',
      }),
    ),
  ).annotate({
    description:
      'Set of [key-value pairs](https://docs.stripe.com/api/metadata) that you can attach to an object. This can be useful for storing additional information about the object in a structured format.',
  }),
  nickname: Schema.optionalKey(
    Schema.NullOr(
      Schema.String.check(
        Schema.makeFilter((input) => [...input].length <= 5000, {
          expected: 'a string of at most 5000 characters',
        }),
      ),
    ).annotate({ description: 'A brief description of the price, hidden from customers.' }),
  ),
  object: Schema.Literal('price').annotate({
    description:
      "String representing the object's type. Objects of the same type share the same value.",
  }),
  product: Schema.Union([
    Schema.String.check(
      Schema.makeFilter((input) => [...input].length <= 5000, {
        expected: 'a string of at most 5000 characters',
      }),
    ),
    Schema.suspend(() => ProductSchema),
    DeletedProductSchema,
  ]).annotate({ description: 'The ID of the product this price is associated with.' }),
  recurring: Schema.optionalKey(
    Schema.NullOr(Schema.Union([RecurringSchema])).annotate({
      description: 'The recurring components of a price such as `interval` and `usage_type`.',
    }),
  ),
  tax_behavior: Schema.optionalKey(
    Schema.NullOr(Schema.Literals(['exclusive', 'inclusive', 'unspecified'])).annotate({
      description:
        'Only required if a [default tax behavior](https://docs.stripe.com/tax/products-prices-tax-categories-tax-behavior#setting-a-default-tax-behavior-(recommended)) was not provided in the Stripe Tax settings. Specifies whether the price is considered inclusive of taxes or exclusive of taxes. One of `inclusive`, `exclusive`, or `unspecified`. Once specified as either `inclusive` or `exclusive`, it cannot be changed.',
    }),
  ),
  tiers: Schema.optionalKey(
    Schema.Array(PriceTierSchema).annotate({
      description:
        'Each element represents a pricing tier. This parameter requires `billing_scheme` to be set to `tiered`. See also the documentation for `billing_scheme`.',
    }),
  ),
  tiers_mode: Schema.optionalKey(
    Schema.NullOr(Schema.Literals(['graduated', 'volume'])).annotate({
      description:
        'Defines if the tiering price should be `graduated` or `volume` based. In `volume`-based tiering, the maximum quantity within a period determines the per unit price. In `graduated` tiering, pricing can change as the quantity grows.',
    }),
  ),
  transform_quantity: Schema.optionalKey(
    Schema.NullOr(Schema.Union([TransformQuantitySchema])).annotate({
      description:
        'Apply a transformation to the reported usage or set quantity before computing the amount billed. Cannot be combined with `tiers`.',
    }),
  ),
  type: Schema.Literals(['one_time', 'recurring']).annotate({
    description:
      'One of `one_time` or `recurring` depending on whether the price is for a one-time purchase or a recurring (subscription) purchase.',
  }),
  unit_amount: Schema.optionalKey(
    Schema.NullOr(Schema.Number.check(Schema.isInt())).annotate({
      description:
        'The unit amount in cents (or local equivalent) to be charged, represented as a whole integer if possible. Only set if `billing_scheme=per_unit`.',
    }),
  ),
  unit_amount_decimal: Schema.optionalKey(
    Schema.NullOr(Schema.String).annotate({
      description:
        'The unit amount in cents (or local equivalent) to be charged, represented as a decimal string with at most 12 decimal places. Only set if `billing_scheme=per_unit`.',
    }),
  ),
}).annotate({
  description:
    'Prices define the unit cost, currency, and (optional) billing cycle for both recurring and one-time purchases of products.\n[Products](https://docs.stripe.com/api#products) help you track inventory or provisioning, and prices help you track payment terms. Different physical goods or levels of service should be represented by products, and pricing options should be represented by prices. This approach lets you change prices without having to change your provisioning scheme.\n\nFor example, you might have a single "gold" product that has prices for $10/month, $100/year, and €9 once.\n\nRelated guides: [Set up a subscription](https://docs.stripe.com/billing/subscriptions/set-up-subscription), [create an invoice](https://docs.stripe.com/billing/invoices/create), and more about [products and prices](https://docs.stripe.com/products-prices/overview).',
})

