  metadata: { [key: string]: string }
  network_data?: Schema.Schema.Type<typeof IssuingTransactionNetworkDataSchema>
  object: 'issuing.transaction'
  purchase_details?: Schema.Schema.Type<typeof IssuingTransactionPurchaseDetailsSchema>
