type TopupType = {
  amount: number
  balance_transaction?: string | Schema.Schema.Type<typeof BalanceTransactionSchema>
  created: number
  currency: string
  description?: string | null
  expected_availability_date?: number | null
  failure_code?: string | null
  failure_message?: string | null
  id: string
  initiated_by?: 'stripe' | 'user'
  livemode: boolean
  metadata: { [key: string]: string }
  object: 'topup'
  payment_method?: string | Schema.Schema.Type<typeof PaymentMethodSchema>
  payment_method_options?: Schema.Schema.Type<typeof TopupResourcePaymentMethodOptionsSchema>
  source?: Schema.Schema.Type<typeof SourceSchema>
  statement_descriptor?: string | null
  status: 'canceled' | 'failed' | 'pending' | 'reversed' | 'succeeded'
  transfer_group?: string | null
}

export const TopupSchema: Schema.Codec<TopupType, unknown> = Schema.Struct({
  amount: Schema.Number.check(Schema.isInt()).annotate({ description: 'Amount transferred.' }),
  balance_transaction: Schema.optionalKey(
    Schema.NullOr(
      Schema.Union([
        Schema.String.check(
          Schema.makeFilter((input) => [...input].length <= 5000, {
            expected: 'a string of at most 5000 characters',
          }),
        ),
        Schema.suspend(() => BalanceTransactionSchema),
      ]),
    ).annotate({
      description:
        'ID of the balance transaction that describes the impact of this top-up on your account balance. May not be specified depending on status of top-up.',
    }),
  ),
  created: Schema.Number.check(Schema.isInt()).annotate({
    description: 'Time at which the object was created. Measured in seconds since the Unix epoch.',
  }),
  currency: Schema.String.check(
    Schema.makeFilter((input) => [...input].length <= 5000, {
      expected: 'a string of at most 5000 characters',
    }),
  ).annotate({
    description:
      'Three-letter [ISO currency code](https://www.iso.org/iso-4217-currency-codes.html), in lowercase. Must be a [supported currency](https://stripe.com/docs/currencies).',
  }),
  description: Schema.optionalKey(
    Schema.NullOr(
      Schema.String.check(
        Schema.makeFilter((input) => [...input].length <= 5000, {
          expected: 'a string of at most 5000 characters',
        }),
      ),
    ).annotate({
      description:
        'An arbitrary string attached to the object. Often useful for displaying to users.',
    }),
  ),
  expected_availability_date: Schema.optionalKey(
    Schema.NullOr(Schema.Number.check(Schema.isInt())).annotate({
      description:
        'Date the funds are expected to arrive in your Stripe account for payouts. This factors in delays like weekends or bank holidays. May not be specified depending on status of top-up.',
    }),
  ),
  failure_code: Schema.optionalKey(
    Schema.NullOr(
      Schema.String.check(
        Schema.makeFilter((input) => [...input].length <= 5000, {
          expected: 'a string of at most 5000 characters',
        }),
      ),
    ).annotate({
      description:
        'Error code explaining reason for top-up failure if available (see [the errors section](/api/errors) for a list of codes).',
    }),
  ),
  failure_message: Schema.optionalKey(
    Schema.NullOr(
      Schema.String.check(
        Schema.makeFilter((input) => [...input].length <= 5000, {
          expected: 'a string of at most 5000 characters',
        }),
      ),
    ).annotate({
      description: 'Message to user further explaining reason for top-up failure if available.',
    }),
  ),
  id: Schema.String.check(
    Schema.makeFilter((input) => [...input].length <= 5000, {
      expected: 'a string of at most 5000 characters',
    }),
  ).annotate({ description: 'Unique identifier for the object.' }),
  initiated_by: Schema.optionalKey(
    Schema.NullOr(Schema.Literals(['stripe', 'user'])).annotate({
      description: 'Indicates whether the top-up was initiated by Stripe or by the user.',
    }),
  ),
  livemode: Schema.Boolean.annotate({
    description:
      'If the object exists in live mode, the value is `true`. If the object exists in test mode, the value is `false`.',
  }),
  metadata: Schema.Record(
    Schema.String,
    Schema.String.check(
      Schema.makeFilter((input) => [...input].length <= 500, {
        expected: 'a string of at most 500 characters',
      }),
    ),
  ).annotate({
    description:
      'Set of [key-value pairs](https://docs.stripe.com/api/metadata) that you can attach to an object. This can be useful for storing additional information about the object in a structured format.',
  }),
  object: Schema.Literal('topup').annotate({
    description:
      "String representing the object's type. Objects of the same type share the same value.",
  }),
  payment_method: Schema.optionalKey(
    Schema.NullOr(
      Schema.Union([
        Schema.String.check(
          Schema.makeFilter((input) => [...input].length <= 5000, {
            expected: 'a string of at most 5000 characters',
          }),
        ),
        Schema.suspend(() => PaymentMethodSchema),
      ]),
    ).annotate({
      description:
        'The ID of a PaymentMethod representing the payment method used for the top-up. A PaymentMethod of type `us_bank_account` can be used.',
    }),
  ),
  payment_method_options: Schema.optionalKey(
    Schema.NullOr(Schema.Union([TopupResourcePaymentMethodOptionsSchema])).annotate({
      description: 'Payment-method-specific configuration for this top-up.',
    }),
  ),
  source: Schema.optionalKey(
    Schema.NullOr(Schema.Union([SourceSchema])).annotate({
      description:
        'The source field is deprecated. It might not always be present in the API response.',
    }),
  ),
  statement_descriptor: Schema.optionalKey(
    Schema.NullOr(
      Schema.String.check(
        Schema.makeFilter((input) => [...input].length <= 5000, {
          expected: 'a string of at most 5000 characters',
        }),
      ),
    ).annotate({
      description:
        "Extra information about a top-up. This will appear on your source's bank statement. It must contain at least one letter.",
    }),
  ),
  status: Schema.Literals(['canceled', 'failed', 'pending', 'reversed', 'succeeded']).annotate({
    description:
      'The status of the top-up is either `canceled`, `failed`, `pending`, `reversed`, or `succeeded`.',
  }),
  transfer_group: Schema.optionalKey(
    Schema.NullOr(
      Schema.String.check(
        Schema.makeFilter((input) => [...input].length <= 5000, {
          expected: 'a string of at most 5000 characters',
        }),
      ),
    ).annotate({ description: 'A string that identifies this top-up as part of a group.' }),
  ),
}).annotate({
  description:
    'To top up your Stripe balance, you create a top-up object. You can retrieve\nindividual top-ups, as well as list all top-ups. Top-ups are identified by a\nunique, random ID.\n\nRelated guide: [Topping up your platform account](https://docs.stripe.com/connect/top-ups)',
})

export type TopupSchema = Schema.Schema.Type<typeof TopupSchema>

