export type SepaDebitGeneratedFromSchema = Schema.Schema.Type<typeof SepaDebitGeneratedFromSchema>

type SubscriptionType = {
  application?:
    | string
    | Schema.Schema.Type<typeof ApplicationSchema>
    | Schema.Schema.Type<typeof DeletedApplicationSchema>
  application_fee_percent?: number | null
  automatic_tax: Schema.Schema.Type<typeof SubscriptionAutomaticTaxSchema>
  billing_cycle_anchor: number
  billing_cycle_anchor_config?: Schema.Schema.Type<
    typeof SubscriptionsResourceBillingCycleAnchorConfigSchema
  >
  billing_mode: Schema.Schema.Type<typeof SubscriptionsResourceBillingModeSchema>
  billing_schedules: readonly Schema.Schema.Type<
    typeof SubscriptionsResourceBillingSchedulesSchema
  >[]
  billing_thresholds?: Schema.Schema.Type<typeof SubscriptionBillingThresholdsSchema>
  cancel_at?: number | null
  cancel_at_period_end: boolean
  canceled_at?: number | null
  cancellation_details?: Schema.Schema.Type<typeof CancellationDetailsSchema>
  collection_method: 'charge_automatically' | 'send_invoice'
  created: number
  currency: string
  customer:
    | string
    | Schema.Schema.Type<typeof CustomerSchema>
    | Schema.Schema.Type<typeof DeletedCustomerSchema>
  customer_account?: string | null
  days_until_due?: number | null
  default_payment_method?: string | Schema.Schema.Type<typeof PaymentMethodSchema>
  default_source?:
    | string
    | Schema.Schema.Type<typeof BankAccountSchema>
    | Schema.Schema.Type<typeof CardSchema>
    | Schema.Schema.Type<typeof SourceSchema>
  default_tax_rates?: readonly Schema.Schema.Type<typeof TaxRateSchema>[] | null
  description?: string | null
  discounts: readonly (string | Schema.Schema.Type<typeof DiscountSchema>)[]
  ended_at?: number | null
  id: string
  invoice_settings: Schema.Schema.Type<
    typeof SubscriptionsResourceSubscriptionInvoiceSettingsSchema
  >
  items: {
    data: readonly Schema.Schema.Type<typeof SubscriptionItemSchema>[]
    has_more: boolean
    object: 'list'
    url: string
  }
  latest_invoice?: string | Schema.Schema.Type<typeof InvoiceSchema>
  livemode: boolean
  managed_payments?: Schema.Schema.Type<typeof SmorResourceManagedPaymentsSchema>
  metadata: { [key: string]: string }
  next_pending_invoice_item_invoice?: number | null
  object: 'subscription'
  on_behalf_of?: string | Schema.Schema.Type<typeof AccountSchema>
  pause_collection?: Schema.Schema.Type<typeof SubscriptionsResourcePauseCollectionSchema>
  payment_settings?: Schema.Schema.Type<typeof SubscriptionsResourcePaymentSettingsSchema>
  pending_invoice_item_interval?: Schema.Schema.Type<
    typeof SubscriptionPendingInvoiceItemIntervalSchema
  >
  pending_setup_intent?: string | Schema.Schema.Type<typeof SetupIntentSchema>
  pending_update?: Schema.Schema.Type<typeof SubscriptionsResourcePendingUpdateSchema>
  presentment_details?: Schema.Schema.Type<
    typeof SubscriptionsResourceSubscriptionPresentmentDetailsSchema
  >
  schedule?: string | Schema.Schema.Type<typeof SubscriptionScheduleSchema>
  start_date: number
  status:
    | 'active'
    | 'canceled'
    | 'incomplete'
    | 'incomplete_expired'
    | 'past_due'
    | 'paused'
    | 'trialing'
    | 'unpaid'
  status_details?: Schema.Schema.Type<typeof SubscriptionsResourceStatusDetailsPublicSchema>
  test_clock?: string | Schema.Schema.Type<typeof TestHelpersTestClockSchema>
  transfer_data?: Schema.Schema.Type<typeof SubscriptionTransferDataSchema>
  trial_end?: number | null
  trial_settings?: Schema.Schema.Type<typeof SubscriptionsResourceTrialSettingsTrialSettingsSchema>
  trial_start?: number | null
}

export const SubscriptionSchema: Schema.Codec<SubscriptionType, unknown> = Schema.Struct({
  application: Schema.optionalKey(
    Schema.NullOr(
      Schema.Union([
        Schema.String.check(
          Schema.makeFilter((input) => [...input].length <= 5000, {
            expected: 'a string of at most 5000 characters',
          }),
        ),
        ApplicationSchema,
        DeletedApplicationSchema,
      ]),
    ).annotate({ description: 'ID of the Connect Application that created the subscription.' }),
  ),
  application_fee_percent: Schema.optionalKey(
    Schema.NullOr(Schema.Number).annotate({
      description:
        "A non-negative decimal between 0 and 100, with at most two decimal places. This represents the percentage of the subscription invoice total that will be transferred to the application owner's Stripe account.",
    }),
  ),
  automatic_tax: Schema.suspend(() => SubscriptionAutomaticTaxSchema),
  billing_cycle_anchor: Schema.Number.check(Schema.isInt()).annotate({
    description:
      'The reference point that aligns future [billing cycle](https://docs.stripe.com/subscriptions/billing-cycle) dates. It sets the day of week for `week` intervals, the day of month for `month` and `year` intervals, and the month of year for `year` intervals. The timestamp is in UTC format.',
  }),
  billing_cycle_anchor_config: Schema.optionalKey(
    Schema.NullOr(Schema.Union([SubscriptionsResourceBillingCycleAnchorConfigSchema])).annotate({
      description: 'The fixed values used to calculate the `billing_cycle_anchor`.',
    }),
  ),
  billing_mode: SubscriptionsResourceBillingModeSchema,
  billing_schedules: Schema.Array(SubscriptionsResourceBillingSchedulesSchema).annotate({
    description: 'Billing schedules for this subscription.',
  }),
  billing_thresholds: Schema.optionalKey(
    Schema.NullOr(Schema.Union([SubscriptionBillingThresholdsSchema])).annotate({
      description:
        'Define thresholds at which an invoice will be sent, and the subscription advanced to a new billing period',
    }),
  ),
  cancel_at: Schema.optionalKey(
    Schema.NullOr(Schema.Number.check(Schema.isInt())).annotate({
      description: 'A date in the future at which the subscription will automatically get canceled',
    }),
  ),
  cancel_at_period_end: Schema.Boolean.annotate({
    description:
      'Whether this subscription will (if `status=active`) or did (if `status=canceled`) cancel at the end of the current billing period.',
  }),
  canceled_at: Schema.optionalKey(
    Schema.NullOr(Schema.Number.check(Schema.isInt())).annotate({
      description:
        'If the subscription has been canceled, the date of that cancellation. If the subscription was canceled with `cancel_at_period_end`, `canceled_at` will reflect the time of the most recent update request, not the end of the subscription period when the subscription is automatically moved to a canceled state.',
    }),
  ),
  cancellation_details: Schema.optionalKey(
    Schema.NullOr(Schema.Union([CancellationDetailsSchema])).annotate({
      description: 'Details about why this subscription was cancelled',
    }),
  ),
  collection_method: Schema.Literals(['charge_automatically', 'send_invoice']).annotate({
    description:
      'Either `charge_automatically`, or `send_invoice`. When charging automatically, Stripe will attempt to pay this subscription at the end of the cycle using the default source attached to the customer. When sending an invoice, Stripe will email your customer an invoice with payment instructions and mark the subscription as `active`.',
  }),
  created: Schema.Number.check(Schema.isInt()).annotate({
    description: 'Time at which the object was created. Measured in seconds since the Unix epoch.',
  }),
  currency: Schema.String.annotate({
    description:
      'Three-letter [ISO currency code](https://www.iso.org/iso-4217-currency-codes.html), in lowercase. Must be a [supported currency](https://stripe.com/docs/currencies).',
  }),
  customer: Schema.Union([
    Schema.String.check(
      Schema.makeFilter((input) => [...input].length <= 5000, {
        expected: 'a string of at most 5000 characters',
      }),
    ),
    Schema.suspend(() => CustomerSchema),
    DeletedCustomerSchema,
  ]).annotate({ description: 'ID of the customer who owns the subscription.' }),
  customer_account: Schema.optionalKey(
    Schema.NullOr(
      Schema.String.check(
        Schema.makeFilter((input) => [...input].length <= 5000, {
          expected: 'a string of at most 5000 characters',
        }),
      ),
    ).annotate({
      description: 'ID of the account representing the customer who owns the subscription.',
    }),
  ),
  days_until_due: Schema.optionalKey(
    Schema.NullOr(Schema.Number.check(Schema.isInt())).annotate({
      description:
        'Number of days a customer has to pay invoices generated by this subscription. This value will be `null` for subscriptions where `collection_method=charge_automatically`.',
    }),
  ),
  default_payment_method: Schema.optionalKey(
    Schema.NullOr(
      Schema.Union([
        Schema.String.check(
          Schema.makeFilter((input) => [...input].length <= 5000, {
            expected: 'a string of at most 5000 characters',
          }),
        ),
        Schema.suspend(() => PaymentMethodSchema),
      ]),
    ).annotate({
      description:
        "ID of the default payment method for the subscription. It must belong to the customer associated with the subscription. This takes precedence over `default_source`. If neither are set, invoices will use the customer's [invoice_settings.default_payment_method](https://docs.stripe.com/api/customers/object#customer_object-invoice_settings-default_payment_method) or [default_source](https://docs.stripe.com/api/customers/object#customer_object-default_source).",
    }),
  ),
  default_source: Schema.optionalKey(
    Schema.NullOr(
      Schema.Union([
        Schema.String.check(
          Schema.makeFilter((input) => [...input].length <= 5000, {
            expected: 'a string of at most 5000 characters',
          }),
        ),
        Schema.suspend(() => BankAccountSchema),
        Schema.suspend(() => CardSchema),
        SourceSchema,
      ]),
    ).annotate({
      description:
        "ID of the default payment source for the subscription. It must belong to the customer associated with the subscription and be in a chargeable state. If `default_payment_method` is also set, `default_payment_method` will take precedence. If neither are set, invoices will use the customer's [invoice_settings.default_payment_method](https://docs.stripe.com/api/customers/object#customer_object-invoice_settings-default_payment_method) or [default_source](https://docs.stripe.com/api/customers/object#customer_object-default_source).",
    }),
  ),
  default_tax_rates: Schema.optionalKey(
    Schema.NullOr(Schema.Array(TaxRateSchema)).annotate({
      description:
        'The tax rates that will apply to any subscription item that does not have `tax_rates` set. Invoices created will have their `default_tax_rates` populated from the subscription.',
    }),
  ),
  description: Schema.optionalKey(
    Schema.NullOr(
      Schema.String.check(
        Schema.makeFilter((input) => [...input].length <= 500, {
          expected: 'a string of at most 500 characters',
        }),
      ),
    ).annotate({
      description:
        "The subscription's description, meant to be displayable to the customer. Use this field to optionally store an explanation of the subscription for rendering in Stripe surfaces and certain local payment methods UIs.",
    }),
  ),
  discounts: Schema.Array(
    Schema.Union([
      Schema.String.check(
        Schema.makeFilter((input) => [...input].length <= 5000, {
          expected: 'a string of at most 5000 characters',
        }),
      ),
      Schema.suspend(() => DiscountSchema),
    ]),
  ).annotate({
    description:
      'The discounts applied to the subscription. Subscription item discounts are applied before subscription discounts. Use `expand[]=discounts` to expand each discount.',
  }),
  ended_at: Schema.optionalKey(
    Schema.NullOr(Schema.Number.check(Schema.isInt())).annotate({
      description: 'If the subscription has ended, the date the subscription ended.',
    }),
  ),
  id: Schema.String.check(
    Schema.makeFilter((input) => [...input].length <= 5000, {
      expected: 'a string of at most 5000 characters',
    }),
  ).annotate({ description: 'Unique identifier for the object.' }),
  invoice_settings: Schema.suspend(() => SubscriptionsResourceSubscriptionInvoiceSettingsSchema),
  items: Schema.Struct({
    data: Schema.Array(Schema.suspend(() => SubscriptionItemSchema)).annotate({
      description: 'Details about each object.',
    }),
    has_more: Schema.Boolean.annotate({
      description:
        'True if this list has another page of items after this one that can be fetched.',
    }),
    object: Schema.Literal('list').annotate({
      description:
        "String representing the object's type. Objects of the same type share the same value. Always has the value `list`.",
    }),
    url: Schema.String.check(
      Schema.makeFilter((input) => [...input].length <= 5000, {
        expected: 'a string of at most 5000 characters',
      }),
    ).annotate({ description: 'The URL where this list can be accessed.' }),
  }).annotate({ description: 'List of subscription items, each with an attached price.' }),
  latest_invoice: Schema.optionalKey(
    Schema.NullOr(
      Schema.Union([
        Schema.String.check(
          Schema.makeFilter((input) => [...input].length <= 5000, {
            expected: 'a string of at most 5000 characters',
          }),
        ),
        Schema.suspend(() => InvoiceSchema),
      ]),
    ).annotate({
      description:
        'The most recent invoice this subscription has generated over its lifecycle (for example, when it cycles or is updated).',
    }),
  ),
  livemode: Schema.Boolean.annotate({
    description:
      'If the object exists in live mode, the value is `true`. If the object exists in test mode, the value is `false`.',
  }),
  managed_payments: Schema.optionalKey(
    Schema.NullOr(Schema.Union([SmorResourceManagedPaymentsSchema])).annotate({
      description:
        'Settings for Managed Payments for this Subscription and resulting [Invoices](/api/invoices/object) and [PaymentIntents](/api/payment_intents/object).',
    }),
  ),
  metadata: Schema.Record(
    Schema.String,
    Schema.String.check(
      Schema.makeFilter((input) => [...input].length <= 500, {
        expected: 'a string of at most 500 characters',
      }),
    ),
  ).annotate({
    description:
      'Set of [key-value pairs](https://docs.stripe.com/api/metadata) that you can attach to an object. This can be useful for storing additional information about the object in a structured format.',
  }),
  next_pending_invoice_item_invoice: Schema.optionalKey(
    Schema.NullOr(Schema.Number.check(Schema.isInt())).annotate({
      description:
        'Specifies the approximate timestamp on which any pending invoice items will be billed according to the schedule provided at `pending_invoice_item_interval`.',
    }),
  ),
  object: Schema.Literal('subscription').annotate({
    description:
      "String representing the object's type. Objects of the same type share the same value.",
  }),
  on_behalf_of: Schema.optionalKey(
    Schema.NullOr(
      Schema.Union([
        Schema.String.check(
          Schema.makeFilter((input) => [...input].length <= 5000, {
            expected: 'a string of at most 5000 characters',
          }),
        ),
        Schema.suspend(() => AccountSchema),
      ]),
    ).annotate({
      description:
        'The account (if any) the charge was made on behalf of for charges associated with this subscription. See the [Connect documentation](https://docs.stripe.com/connect/subscriptions#on-behalf-of) for details.',
    }),
  ),
  pause_collection: Schema.optionalKey(
    Schema.NullOr(Schema.Union([SubscriptionsResourcePauseCollectionSchema])).annotate({
      description:
        'If specified, payment collection for this subscription will be paused. Note that the subscription status will be unchanged and will not be updated to `paused`. Learn more about [pausing collection](https://docs.stripe.com/billing/subscriptions/pause-payment).',
    }),
  ),
  payment_settings: Schema.optionalKey(
    Schema.NullOr(Schema.Union([SubscriptionsResourcePaymentSettingsSchema])).annotate({
      description: 'Payment settings passed on to invoices created by the subscription.',
    }),
  ),
  pending_invoice_item_interval: Schema.optionalKey(
    Schema.NullOr(Schema.Union([SubscriptionPendingInvoiceItemIntervalSchema])).annotate({
      description:
        'Specifies an interval for how often to bill for any pending invoice items. It is analogous to calling [Create an invoice](/api/invoices/create) for the given subscription at the specified interval.',
    }),
  ),
  pending_setup_intent: Schema.optionalKey(
    Schema.NullOr(
      Schema.Union([
        Schema.String.check(
          Schema.makeFilter((input) => [...input].length <= 5000, {
            expected: 'a string of at most 5000 characters',
          }),
        ),
        Schema.suspend(() => SetupIntentSchema),
      ]),
    ).annotate({
      description:
        "You can use this [SetupIntent](https://docs.stripe.com/api/setup_intents) to collect user authentication when creating a subscription without immediate payment or updating a subscription's payment method, allowing you to optimize for off-session payments. Learn more in the [SCA Migration Guide](https://docs.stripe.com/billing/migration/strong-customer-authentication#scenario-2).",
    }),
  ),
  pending_update: Schema.optionalKey(
    Schema.NullOr(
      Schema.Union([Schema.suspend(() => SubscriptionsResourcePendingUpdateSchema)]),
    ).annotate({
      description:
        'If specified, [pending updates](https://docs.stripe.com/billing/subscriptions/pending-updates) that will be applied to the subscription once the `latest_invoice` has been paid.',
    }),
  ),
  presentment_details: Schema.optionalKey(
    SubscriptionsResourceSubscriptionPresentmentDetailsSchema,
  ),
  schedule: Schema.optionalKey(
    Schema.NullOr(
      Schema.Union([
        Schema.String.check(
          Schema.makeFilter((input) => [...input].length <= 5000, {
            expected: 'a string of at most 5000 characters',
          }),
        ),
        Schema.suspend(() => SubscriptionScheduleSchema),
      ]),
    ).annotate({ description: 'The schedule attached to the subscription' }),
  ),
  start_date: Schema.Number.check(Schema.isInt()).annotate({
    description:
      'Date when the subscription was first created. The date might differ from the `created` date due to backdating.',
  }),
  status: Schema.Literals([
    'active',
    'canceled',
    'incomplete',
    'incomplete_expired',
    'past_due',
    'paused',
    'trialing',
    'unpaid',
  ]).annotate({
    description:
      "Possible values are `incomplete`, `incomplete_expired`, `trialing`, `active`, `past_due`, `canceled`, `unpaid`, or `paused`. \n\nFor `collection_method=charge_automatically` a subscription moves into `incomplete` if the initial payment attempt fails. A subscription in this status can only have metadata and default_source updated. Once the first invoice is paid, the subscription moves into an `active` status. If the first invoice is not paid within 23 hours, the subscription transitions to `incomplete_expired`. This is a terminal status, the open invoice will be voided and no further invoices will be generated. \n\nA subscription that is currently in a trial period is `trialing` and moves to `active` when the trial period is over. \n\nA subscription can only enter a `paused` status [when a trial ends without a payment method](https://docs.stripe.com/billing/subscriptions/trials/free-trials#create-free-trials-without-payment). A `paused` subscription doesn't generate invoices and can be resumed after your customer adds their payment method. The `paused` status is different from [pausing collection](https://docs.stripe.com/billing/subscriptions/pause-payment), which still generates invoices and leaves the subscription's status unchanged. \n\nIf subscription `collection_method=charge_automatically`, it becomes `past_due` when payment is required but cannot be paid (due to failed payment or awaiting additional user actions). Once Stripe has exhausted all payment retry attempts, the subscription will become `canceled` or `unpaid` (depending on your subscriptions settings). \n\nIf subscription `collection_method=send_invoice` it becomes `past_due` when its invoice is not paid by the due date, and `canceled` or `unpaid` if it is still not paid by an additional deadline after that. Note that when a subscription has a status of `unpaid`, no subsequent invoices will be attempted (invoices will be created, but then immediately automatically closed). After receiving updated payment information from a customer, you may choose to reopen and pay their closed invoices.",
  }),
  status_details: Schema.optionalKey(SubscriptionsResourceStatusDetailsPublicSchema),
  test_clock: Schema.optionalKey(
    Schema.NullOr(
      Schema.Union([
        Schema.String.check(
          Schema.makeFilter((input) => [...input].length <= 5000, {
            expected: 'a string of at most 5000 characters',
          }),
        ),
        TestHelpersTestClockSchema,
      ]),
    ).annotate({ description: 'ID of the test clock this subscription belongs to.' }),
  ),
  transfer_data: Schema.optionalKey(
    Schema.NullOr(Schema.Union([Schema.suspend(() => SubscriptionTransferDataSchema)])).annotate({
      description:
        "The account (if any) the subscription's payments will be attributed to for tax reporting, and where funds from each payment will be transferred to for each of the subscription's invoices.",
    }),
  ),
  trial_end: Schema.optionalKey(
    Schema.NullOr(Schema.Number.check(Schema.isInt())).annotate({
      description: 'If the subscription has a trial, the end of that trial.',
    }),
  ),
  trial_settings: Schema.optionalKey(
    Schema.NullOr(Schema.Union([SubscriptionsResourceTrialSettingsTrialSettingsSchema])).annotate({
      description: 'Settings related to subscription trials.',
    }),
  ),
  trial_start: Schema.optionalKey(
    Schema.NullOr(Schema.Number.check(Schema.isInt())).annotate({
      description: 'If the subscription has a trial, the beginning of that trial.',
    }),
  ),
}).annotate({
  description:
    'Subscriptions allow you to charge a customer on a recurring basis.\n\nRelated guide: [Creating subscriptions](https://docs.stripe.com/billing/subscriptions/creating)',
})

