export const AccountSessionSchema = Schema.Struct({
  account: Schema.String.check(
    Schema.makeFilter((input) => [...input].length <= 5000, {
      expected: 'a string of at most 5000 characters',
    }),
  ).annotate({ description: 'The ID of the account the AccountSession was created for' }),
  client_secret: Schema.String.check(
    Schema.makeFilter((input) => [...input].length <= 5000, {
      expected: 'a string of at most 5000 characters',
    }),
  ).annotate({
    description:
      'The client secret of this AccountSession. Used on the client to set up secure access to the given `account`.\n\nThe client secret can be used to provide access to `account` from your frontend. It should not be stored, logged, or exposed to anyone other than the connected account. Make sure that you have TLS enabled on any page that includes the client secret.\n\nRefer to our docs to [setup Connect embedded components](https://docs.stripe.com/connect/get-started-connect-embedded-components) and learn about how `client_secret` should be handled.',
  }),
  components: ConnectEmbeddedAccountSessionCreateComponentsSchema,
  expires_at: Schema.Number.check(Schema.isInt()).annotate({
    description: 'The timestamp at which this AccountSession will expire.',
  }),
  livemode: Schema.Boolean.annotate({
    description:
      'If the object exists in live mode, the value is `true`. If the object exists in test mode, the value is `false`.',
  }),
  object: Schema.Literal('account_session').annotate({
    description:
      "String representing the object's type. Objects of the same type share the same value.",
  }),
}).annotate({
  description:
    'An AccountSession allows a Connect platform to grant access to a connected account in Connect embedded components.\n\nWe recommend that you create an AccountSession each time you need to display an embedded component\nto your user. Do not save AccountSessions to your database as they expire relatively\nquickly, and cannot be used more than once.\n\nRelated guide: [Connect embedded components](https://docs.stripe.com/connect/get-started-connect-embedded-components)',
})

export type AccountSessionSchema = Schema.Schema.Type<typeof AccountSessionSchema>

