export const AppsInstallSchema = Schema.Struct({
  account: Schema.String.check(
    Schema.makeFilter((input) => [...input].length <= 5000, {
      expected: 'a string of at most 5000 characters',
    }),
  ).annotate({ description: 'The ID of the account that the app install belongs to.' }),
  app: Schema.String.check(
    Schema.makeFilter((input) => [...input].length <= 5000, {
      expected: 'a string of at most 5000 characters',
    }),
  ).annotate({ description: 'The ID of the app installed.' }),
  approval_required: Schema.Boolean.annotate({
    description:
      'Whether the installer must authorize pending permissions, content security policy entries, or endpoints. For private apps, `approval_required` stays `false`; creating or reauthorizing the install through the API installs the newest completed upload and grants its permissions.',
  }),
  auth_code: Schema.optionalKey(
    Schema.NullOr(
      Schema.String.check(
        Schema.makeFilter((input) => [...input].length <= 5000, {
          expected: 'a string of at most 5000 characters',
        }),
      ),
    ).annotate({ description: 'The authorization code for an oauth app install.' }),
  ),
  channel: Schema.Literals([
    'private_live',
    'private_test',
    'public',
    'review',
    'testing',
  ]).annotate({ description: 'The distribution channel associated with the app install.' }),
  content_security_policy_granted: AppServiceResourceInstallContentSecurityPolicySchema,
  content_security_policy_pending: AppServiceResourceInstallContentSecurityPolicySchema,
  created: Schema.Number.check(Schema.isInt()).annotate({
    description: 'Time at which the object was created. Measured in seconds since the Unix epoch.',
  }),
  created_by: Schema.optionalKey(
    Schema.NullOr(
      Schema.String.check(
        Schema.makeFilter((input) => [...input].length <= 5000, {
          expected: 'a string of at most 5000 characters',
        }),
      ),
    ).annotate({
      description: 'The ID of the embedding platform that created the install, if applicable.',
    }),
  ),
  endpoints_granted: Schema.Array(
    Schema.String.check(
      Schema.makeFilter((input) => [...input].length <= 5000, {
        expected: 'a string of at most 5000 characters',
      }),
    ),
  ).annotate({ description: 'The endpoint URLs authorized by the installer.' }),
  endpoints_pending: Schema.Array(
    Schema.String.check(
      Schema.makeFilter((input) => [...input].length <= 5000, {
        expected: 'a string of at most 5000 characters',
      }),
    ),
  ).annotate({
    description:
      'The endpoint URLs requested by the latest app version that the installer has not authorized.',
  }),
  id: Schema.String.check(
    Schema.makeFilter((input) => [...input].length <= 5000, {
      expected: 'a string of at most 5000 characters',
    }),
  ).annotate({ description: 'Unique identifier for the object.' }),
  livemode: Schema.Boolean.annotate({
    description:
      'If the object exists in live mode, the value is `true`. If the object exists in test mode, the value is `false`.',
  }),
  object: Schema.Literal('apps.install').annotate({
    description:
      "String representing the object's type. Objects of the same type share the same value.",
  }),
  permissions_granted: Schema.Array(
    Schema.String.check(
      Schema.makeFilter((input) => [...input].length <= 5000, {
        expected: 'a string of at most 5000 characters',
      }),
    ),
  ).annotate({ description: 'The permissions authorized by the installer.' }),
  permissions_pending: Schema.Array(
    Schema.String.check(
      Schema.makeFilter((input) => [...input].length <= 5000, {
        expected: 'a string of at most 5000 characters',
      }),
    ),
  ).annotate({
    description:
      'The permissions requested by the latest app version that the installer has not authorized.',
  }),
  status: Schema.Literals([
    'install_failed',
    'installed',
    'installing',
    'uninstall_failed',
    'uninstalling',
  ]).annotate({ description: 'The status of the app install.' }),
}).annotate({
  description:
    "An app install represents a Stripe App that is installed on an account. It reports the permissions,\ncontent security policy entries, and endpoints that the installing account has authorized, along with any\nthat the app's latest version requests but the account has not authorized yet. Use the Install API to\ninstall, reauthorize, and uninstall apps, and to check the state of existing installs.",
})

export type AppsInstallSchema = Schema.Schema.Type<typeof AppsInstallSchema>

