type CustomerBalanceTransactionType = {
  amount: number
  checkout_session?: string | Schema.Schema.Type<typeof CheckoutSessionSchema>
  created: number
  credit_note?: string | Schema.Schema.Type<typeof CreditNoteSchema>
  currency: string
  customer: string | Schema.Schema.Type<typeof CustomerSchema>
  customer_account?: string | null
  description?: string | null
  ending_balance: number
  id: string
  invoice?: string | Schema.Schema.Type<typeof InvoiceSchema>
  livemode: boolean
  metadata?: { [key: string]: string } | null
  object: 'customer_balance_transaction'
  type:
    | 'adjustment'
    | 'applied_to_invoice'
    | 'checkout_session_subscription_payment'
    | 'checkout_session_subscription_payment_canceled'
    | 'credit_note'
    | 'initial'
    | 'invoice_overpaid'
    | 'invoice_too_large'
    | 'invoice_too_small'
    | 'migration'
    | 'unapplied_from_invoice'
    | 'unspent_receiver_credit'
}

