export const SourceMandateNotificationSchema = Schema.Struct({
  acss_debit: Schema.optionalKey(SourceMandateNotificationAcssDebitDataSchema),
  amount: Schema.optionalKey(
    Schema.NullOr(Schema.Number.check(Schema.isInt())).annotate({
      description:
        'A positive integer in the smallest currency unit (that is, 100 cents for $1.00, or 1 for ¥1, Japanese Yen being a zero-decimal currency) representing the amount associated with the mandate notification. The amount is expressed in the currency of the underlying source. Required if the notification type is `debit_initiated`.',
    }),
  ),
  bacs_debit: Schema.optionalKey(SourceMandateNotificationBacsDebitDataSchema),
  created: Schema.Number.check(Schema.isInt()).annotate({
    description: 'Time at which the object was created. Measured in seconds since the Unix epoch.',
  }),
  id: Schema.String.check(
    Schema.makeFilter((input) => [...input].length <= 5000, {
      expected: 'a string of at most 5000 characters',
    }),
  ).annotate({ description: 'Unique identifier for the object.' }),
  livemode: Schema.Boolean.annotate({
    description:
      'If the object exists in live mode, the value is `true`. If the object exists in test mode, the value is `false`.',
  }),
  object: Schema.Literal('source_mandate_notification').annotate({
    description:
      "String representing the object's type. Objects of the same type share the same value.",
  }),
  reason: Schema.String.check(
    Schema.makeFilter((input) => [...input].length <= 5000, {
      expected: 'a string of at most 5000 characters',
    }),
  ).annotate({
    description:
      'The reason of the mandate notification. Valid reasons are `mandate_confirmed` or `debit_initiated`.',
  }),
  sepa_debit: Schema.optionalKey(SourceMandateNotificationSepaDebitDataSchema),
  source: SourceSchema,
  status: Schema.String.check(
    Schema.makeFilter((input) => [...input].length <= 5000, {
      expected: 'a string of at most 5000 characters',
    }),
  ).annotate({
    description:
      'The status of the mandate notification. Valid statuses are `pending` or `submitted`.',
  }),
  type: Schema.String.check(
    Schema.makeFilter((input) => [...input].length <= 5000, {
      expected: 'a string of at most 5000 characters',
    }),
  ).annotate({
    description:
      'The type of source this mandate notification is attached to. Should be the source type identifier code for the payment method, such as `three_d_secure`.',
  }),
}).annotate({
  description:
    'Source mandate notifications should be created when a notification related to\na source mandate must be sent to the payer. They will trigger a webhook or\ndeliver an email to the customer.',
})

export type SourceMandateNotificationSchema = Schema.Schema.Type<
  typeof SourceMandateNotificationSchema
>

