export const SourceTransactionSchema = Schema.Struct({
  ach_credit_transfer: Schema.optionalKey(SourceTransactionAchCreditTransferDataSchema),
  amount: Schema.Number.check(Schema.isInt()).annotate({
    description:
      'A positive integer in the smallest currency unit (that is, 100 cents for $1.00, or 1 for ¥1, Japanese Yen being a zero-decimal currency) representing the amount your customer has pushed to the receiver.',
  }),
  chf_credit_transfer: Schema.optionalKey(SourceTransactionChfCreditTransferDataSchema),
  created: Schema.Number.check(Schema.isInt()).annotate({
    description: 'Time at which the object was created. Measured in seconds since the Unix epoch.',
  }),
  currency: Schema.String.annotate({
    description:
      'Three-letter [ISO currency code](https://www.iso.org/iso-4217-currency-codes.html), in lowercase. Must be a [supported currency](https://stripe.com/docs/currencies).',
  }),
  gbp_credit_transfer: Schema.optionalKey(SourceTransactionGbpCreditTransferDataSchema),
  id: Schema.String.check(
    Schema.makeFilter((input) => [...input].length <= 5000, {
      expected: 'a string of at most 5000 characters',
    }),
  ).annotate({ description: 'Unique identifier for the object.' }),
  livemode: Schema.Boolean.annotate({
    description:
      'If the object exists in live mode, the value is `true`. If the object exists in test mode, the value is `false`.',
  }),
  object: Schema.Literal('source_transaction').annotate({
    description:
      "String representing the object's type. Objects of the same type share the same value.",
  }),
  paper_check: Schema.optionalKey(SourceTransactionPaperCheckDataSchema),
  sepa_credit_transfer: Schema.optionalKey(SourceTransactionSepaCreditTransferDataSchema),
  source: Schema.String.check(
    Schema.makeFilter((input) => [...input].length <= 5000, {
      expected: 'a string of at most 5000 characters',
    }),
  ).annotate({ description: 'The ID of the source this transaction is attached to.' }),
  status: Schema.String.check(
    Schema.makeFilter((input) => [...input].length <= 5000, {
      expected: 'a string of at most 5000 characters',
    }),
  ).annotate({
    description: 'The status of the transaction, one of `succeeded`, `pending`, or `failed`.',
  }),
  type: Schema.Literals([
    'ach_credit_transfer',
    'ach_debit',
    'alipay',
    'bancontact',
    'card',
    'card_present',
    'eps',
    'giropay',
    'ideal',
    'klarna',
    'multibanco',
    'p24',
    'sepa_debit',
    'sofort',
    'three_d_secure',
    'wechat',
  ]).annotate({ description: 'The type of source this transaction is attached to.' }),
}).annotate({
  description:
    'Some payment methods have no required amount that a customer must send.\nCustomers can be instructed to send any amount, and it can be made up of\nmultiple transactions. As such, sources can have multiple associated\ntransactions.',
})

export type SourceTransactionSchema = Schema.Schema.Type<typeof SourceTransactionSchema>

